//! The hooks library of hilavitkutin's bench tree.
//!
//! The driver `mock bench run` generates from `bench.toml` compiles this file
//! in by path and calls `hooks()`. Every bench whose input is plain bytes runs
//! on the generated byte dispatch, whose points `[dispatch]` in `bench.toml`
//! declares, and every workload program is a `[workload.*]` table there. What
//! is left is what each bench owns:
//!
//! - `routine_for` serves the members whose routine is not a byte routine:
//!   `engine_vs_std` (`Evs<N, W>` by the section's workload),
//!   `single-trunk-convergence` (`Conv<N>` with the input builder of the
//!   section's workload and worker count), `resource_storage`'s `rsb_seqd`
//!   (`SeqAlgo<N>`) and `frame_wide` (`FrameHeavy<N>` or `FrameLight<N>` by the
//!   sweep).
//! - `after_cell` runs what used to run after a member's own loop: the
//!   five-check disassembly gate over every `dispatch_*` cell, the design's
//!   ceilings over every `engine_vs_std` cell, and `frame_wide`'s report, framed
//!   on the `hand` arm under its caveat, with no arm dropped before the
//!   comparison.
//! - `on_init` holds `frame_wide`'s sections to comparing every arm byte for
//!   byte, since every arm computes the same frame.
//!
//! The routine types and every check with tests of its own live in the support
//! crates under `support/`, which the generated driver takes as path
//! dependencies; nothing here is tested on its own, so nothing here decides
//! more than which of them a cell reaches.

use std::collections::BTreeMap;
use std::fmt::Write as _;

use bench_disasm::disasm_5check;
use evs_support::{Evs, Workload as EvsWorkload};
use mockspace_bench_core::routine_bridge;
use mockspace_bench_harness::driver::{AfterCell, CellVerdict, Hooks, InitContext, InitVerdict};
use mockspace_bench_harness::{BenchConfig, RoutineSpec};
use stc_support::workload::{APPEND, FOLD_HEAVY, FOLD_LIGHT};
use stc_support::{Conv, input_bytes};

/// The member names, as `bench` names a member's cells.
const EVS: &str = "engine_vs_std";
const STC: &str = "single-trunk-convergence";
const RSB: &str = "resource_storage";
const FRAME: &str = "frame_wide";

/// The hooks the generated driver runs.
pub fn hooks() -> Hooks {
    Hooks {
        on_init: Some(frame_compares_every_arm),
        routine_for: Some(routine_for),
        after_cell: Some(after_cell),
        ..Hooks::default()
    }
}

/// The routine of a cell that is not a byte routine; `None` falls through to
/// the generated byte dispatch.
fn routine_for(config: &BenchConfig) -> Option<RoutineSpec> {
    let bridge = match config.bench.as_str() {
        EVS => evs_bridge(config)?,
        STC => stc_bridge(config)?,
        RSB if config.bench_name.contains("seqd") => rsb_seqd_bridge(config.n)?,
        FRAME => {
            frame_wide_support::bridge_for(
                config.n,
                frame_wide_support::is_heavy(&config.bench_name)?,
            )?
        },
        _ => return None,
    };
    Some(RoutineSpec {
        name: config.bench_name.rsplit('/').next()?.to_string(),
        bridge,
    })
}

/// `Evs<N, W>` for the section's `workload` and record count.
fn evs_bridge(config: &BenchConfig) -> Option<mockspace_bench_core::RoutineBridge> {
    let workload = EvsWorkload::from_name(&config.workload)?;
    macro_rules! pick {
        ($($n:literal),*) => {
            match (config.n, workload) {
                $(
                    ($n, EvsWorkload::ElementWise) => routine_bridge!(Evs<$n, { EvsWorkload::ElementWise.tag() }>),
                    ($n, EvsWorkload::Branching) => routine_bridge!(Evs<$n, { EvsWorkload::Branching.tag() }>),
                    ($n, EvsWorkload::Accumulator) => routine_bridge!(Evs<$n, { EvsWorkload::Accumulator.tag() }>),
                    ($n, EvsWorkload::WideParallel) => routine_bridge!(Evs<$n, { EvsWorkload::WideParallel.tag() }>),
                )*
                _ => return None,
            }
        };
    }
    Some(pick!(4096, 65536, 1048576, 4194304))
}

/// `Conv<N>` with the input builder for the section's workload and worker
/// count. A section is named `<workload>_w<W>`, with an optional band suffix;
/// `short` is the one-to-four-morsel band of `fold_light`.
fn stc_bridge(config: &BenchConfig) -> Option<mockspace_bench_core::RoutineBridge> {
    let section = stc_support::section::parse(&config.bench_name)?;
    let kind = match section.workload {
        "short" => FOLD_LIGHT,
        name => stc_support::workload::by_name(name)?.id,
    };
    let mut bridge = match config.n {
        16 => routine_bridge!(Conv<16>),
        64 => routine_bridge!(Conv<64>),
        256 => routine_bridge!(Conv<256>),
        1024 => routine_bridge!(Conv<1024>),
        4096 => routine_bridge!(Conv<4096>),
        16384 => routine_bridge!(Conv<16384>),
        65536 => routine_bridge!(Conv<65536>),
        262144 => routine_bridge!(Conv<262144>),
        1048576 => routine_bridge!(Conv<1048576>),
        4194304 => routine_bridge!(Conv<4194304>),
        16777216 => routine_bridge!(Conv<16777216>),
        134217728 => routine_bridge!(Conv<134217728>),
        _ => return None,
    };
    bridge.input_builder = stc_builder(kind, section.workers)?;
    Some(bridge)
}

/// The input builder for workload `kind` at `w` workers.
fn stc_builder(kind: u32, w: u32) -> Option<fn(u64) -> Vec<u8>> {
    macro_rules! by_w {
        ($k:expr) => {
            match w {
                1 => Some(input_bytes::<$k, 1> as fn(u64) -> Vec<u8>),
                2 => Some(input_bytes::<$k, 2>),
                4 => Some(input_bytes::<$k, 4>),
                8 => Some(input_bytes::<$k, 8>),
                _ => None,
            }
        };
    }
    match kind {
        FOLD_LIGHT => by_w!(FOLD_LIGHT),
        FOLD_HEAVY => by_w!(FOLD_HEAVY),
        APPEND => by_w!(APPEND),
        _ => None,
    }
}

/// The seed-driven `SeqAlgo<N>`: a tiny input and an N-element payload built in
/// setup, so the payload size has no stack-array ceiling.
fn rsb_seqd_bridge(n: usize) -> Option<mockspace_bench_core::RoutineBridge> {
    use rsb_kernels::seqd::SeqAlgo;
    Some(match n {
        65536 => routine_bridge!(SeqAlgo<65536>),
        1048576 => routine_bridge!(SeqAlgo<1048576>),
        4194304 => routine_bridge!(SeqAlgo<4194304>),
        16777216 => routine_bridge!(SeqAlgo<16777216>),
        67108864 => routine_bridge!(SeqAlgo<67108864>),
        268435456 => routine_bridge!(SeqAlgo<268435456>),
        _ => return None,
    })
}

/// Every arm of `frame_wide` computes the same frame, so a section that lets
/// the arms differ, or lets a validation failure pass, reads as checked while
/// comparing nothing.
fn frame_compares_every_arm(ctx: &InitContext<'_>) -> InitVerdict {
    for (key, section) in &ctx.manifest.bench {
        if !key.starts_with("frame_wide/") {
            continue;
        }
        if section.may_differ || !section.required {
            return InitVerdict::Abort(format!(
                "bench `{key}`: every arm computes the same frame, so `may_differ` must be false \
                 and `required` true"
            ));
        }
    }
    InitVerdict::Proceed
}

/// What runs after each cell, by the bench the cell belongs to.
fn after_cell(cell: &AfterCell<'_>) -> CellVerdict {
    let config = cell.config;
    if config.bench.starts_with("dispatch_") {
        return five_check(cell);
    }
    match config.bench.as_str() {
        EVS => engine_vs_std(cell),
        FRAME => frame_wide(cell),
        _ => CellVerdict::Pass,
    }
}

/// The axis-A LLVM-transparency gate: the five checks over every arm of a
/// `dispatch_*` cell, the report written into the cell's run directory. A
/// `dispatch_static` failure fails the cell; `dispatch_dynamic` failures are
/// the expected counter-example and are only recorded.
fn five_check(cell: &AfterCell<'_>) -> CellVerdict {
    let config = cell.config;
    match disasm_5check::run_and_write(
        &config.bench_name,
        config.n,
        cell.arm_paths,
        &[config.n as u64],
        cell.out_dir,
    ) {
        Ok(report) if report.any_fail() && config.bench.starts_with("dispatch_static") => {
            CellVerdict::Fail(format!(
                "5-check failed on `{}` n={}: the axis-A LLVM-transparency invariant regressed",
                config.bench_name, config.n
            ))
        },
        Ok(report) if report.any_fail() => {
            CellVerdict::Note("5-check report written, counter-example FAILs expected".into())
        },
        Ok(_) => CellVerdict::Pass,
        Err(e) => CellVerdict::Note(format!("5-check skipped: {e}")),
    }
}

/// `engine_vs_std`: the report without the harness's stock verdict lines, and
/// the design's ceilings held to this cell's warm medians, written beside it
/// as `verdict.md`. A red ceiling is the remaining gap to the design and is
/// recorded, not a failed cell.
fn engine_vs_std(cell: &AfterCell<'_>) -> CellVerdict {
    if let Err(e) = rewrite_report(cell, |report| bench_arm::findings::plain(report)) {
        return CellVerdict::Fail(e);
    }
    let Some(workload) = EvsWorkload::from_name(&cell.config.workload) else {
        return CellVerdict::Fail(format!(
            "section `{}` names no workload: `{}`",
            cell.config.bench_name, cell.config.workload
        ));
    };
    let mut by_arm: BTreeMap<String, Vec<f64>> = BTreeMap::new();
    for s in cell.result.samples.iter().filter(|s| s.mode == "warm") {
        by_arm.entry(s.variant.clone()).or_default().push(s.algo_ns);
    }
    let medians: BTreeMap<String, f64> = by_arm
        .into_iter()
        .map(|(arm, ns)| (arm, mockspace_bench_harness::analysis::median(&ns)))
        .collect();
    let judged = evs_support::verdict::judge(workload, cell.config.n, &medians);
    let mut text = String::from("# The design's ceilings over this run\n\n");
    let mut red = 0usize;
    for j in &judged {
        let colour = if j.green() { "green" } else { "red" };
        red += usize::from(!j.green());
        let _ = writeln!(
            text,
            "- {}: {:.3} against a ceiling of {:.2}, {colour}",
            j.pair, j.ratio, j.ceiling
        );
    }
    if judged.is_empty() {
        text.push_str("No pair of arms this section times is held to a ceiling.\n");
    }
    if let Err(e) = std::fs::write(cell.out_dir.join("verdict.md"), text) {
        return CellVerdict::Fail(format!("writing verdict.md: {e}"));
    }
    match red {
        0 => CellVerdict::Pass,
        _ => CellVerdict::Note(format!("{red} of {} ceilings red", judged.len())),
    }
}

/// The arm every delta in a `frame_wide` report is taken against: the
/// hand-written fused path, which the bench matrix names as the bar the engine
/// is measured against, never an engine arm.
const FRAME_BASELINE: &str = "hand";

/// What a reader opening a `frame_wide` report alone has to see first.
const FRAME_CAVEAT: &str = "\
## Before the numbers

Nothing in this file is a verdict on any arm, and no delta below is a reason to
use one arm over another.

The engine arms measure the engine without its headline features. Op, on 13
November: the engine arms measure something that \"doesn't yet include any of
the actual headline features like fusing and the adaptive trunk/fiber/morsel
crunching on the datadlow-ish schedule. It's bare bones, barely lowers to
anything interesting yet. So no calls should be made based on those yet, they
are a baseline to compare against then.\" An engine number here is a baseline
for a later comparison and decides nothing.

Every delta below is taken against `hand`, the hand-written fused path, rather
than against an engine arm. The bench matrix names `hand` as the bar the engine
is measured against, so a row against it says how far an arm is from what a
person writes for this workload. Where the report says the baseline is the
slowest variant and reads as picked by accident, it was not: it is set in the
bench tree's hooks library, on purpose, and is meant to be the bar whether it
wins or loses. Do not re-baseline on whichever arm happens to be fastest.

The harness writes a `Why it matters` line under each highlight, calling a large
delta a reason to switch and a dominant winner a safe default pick. Those lines
are its stock phrasing for any dataset, they are judgements this file has no
standing to make, and they are stripped before it is written. What is left under
each highlight is the shape of the numbers.

A median here is wall-clock time and carries nothing about how many cores an
arm used to reach it. Two arms with the same median are not the same cost if
one of them ran on one core and the other on two. The occupancy of every
parallel arm is measured separately and stated beside these medians in
`mock/research/202611131400_frame-wide-first-run.md`. Read the two together or
neither.

The generated report follows.

";

/// `frame_wide`: no arm may be dropped before the comparison, and the report is
/// rendered again framed on `hand`, under the caveat, without the stock lines.
fn frame_wide(cell: &AfterCell<'_>) -> CellVerdict {
    if !cell.dropped.is_empty() {
        return CellVerdict::Fail(format!(
            "{} arm(s) were dropped before comparison and none may be: {:?}",
            cell.dropped.len(),
            cell.dropped
        ));
    }
    let Some(routine) = routine_for(cell.config) else {
        return CellVerdict::Fail(format!(
            "bench `{}` has no routine at n={}",
            cell.config.bench_name, cell.config.n
        ));
    };
    let ds = cell
        .result
        .dataset_for_routine(&routine, "warm")
        .with_methodology(cell.config)
        .with_baseline(FRAME_BASELINE);
    // `with_baseline` ignores a name it does not find, and falling back to the
    // first arm is how the report comes out framed on `engine` again.
    let chosen = ds.baseline().name.clone();
    if chosen != FRAME_BASELINE {
        return CellVerdict::Fail(format!(
            "the report baseline is `{chosen}`, not `{FRAME_BASELINE}`: no arm of this cell is \
             named `{FRAME_BASELINE}`, so every delta would be framed on an arm nobody chose"
        ));
    }
    let report = mockspace_bench_harness::generate_report(&ds, &cell.result.title);
    let md = format!("{FRAME_CAVEAT}{}", bench_arm::findings::plain(&report));
    match std::fs::write(
        cell.out_dir
            .join(mockspace_bench_harness::layout::REPORT_FILE),
        md,
    ) {
        Ok(()) => CellVerdict::Pass,
        Err(e) => CellVerdict::Fail(format!("writing the report: {e}")),
    }
}

/// Rewrite the report the driver wrote into the cell's run directory.
fn rewrite_report(cell: &AfterCell<'_>, edit: impl Fn(&str) -> String) -> Result<(), String> {
    let path = cell
        .out_dir
        .join(mockspace_bench_harness::layout::REPORT_FILE);
    let report = std::fs::read_to_string(&path).map_err(|e| format!("{}: {e}", path.display()))?;
    std::fs::write(&path, edit(&report)).map_err(|e| format!("{}: {e}", path.display()))
}
